var myPow = function(x, n) {
    let exp = n;
    if (exp < 0) {
        x = 1 / x;
        exp = -exp;
    }
    let ans = 1;
    let curr = x;
    while (exp > 0) {
        if (exp % 2 === 1) {
            ans *= curr;
        }
        curr *= curr;
        exp = Math.floor(exp / 2);
    }
    return ans;
};
